final class QueueStatsScheduleException extends RuntimeException
{
}

const QUEUE_STATS_WARNING_DIR = '/tmp/nethvoice-queue-stats-reset-warnings';

/**
 * Match one numeric cron field generated by the FreePBX queues UI.
 */
function queue_stats_cron_field_matches(
    ?string $expression,
    int $value,
    int $minimum,
    int $maximum,
    bool $dayOfWeek = false
): bool {
    if ($expression === null) {
        throw new QueueStatsScheduleException('a cron field is missing');
    }

    $expression = trim($expression);
    if ($expression === '*') {
        return true;
    }
    if ($expression === '' || !ctype_digit($expression)) {
        throw new QueueStatsScheduleException("invalid cron field '$expression'");
    }

    $scheduledValue = (int) $expression;
    $fieldMaximum = $dayOfWeek ? 7 : $maximum;
    if ($scheduledValue < $minimum || $scheduledValue > $fieldMaximum) {
        throw new QueueStatsScheduleException("cron field '$expression' is out of range");
    }

    // Cron accepts both 0 and 7 for Sunday.
    if ($dayOfWeek && $scheduledValue === 7) {
        $scheduledValue = 0;
    }

    return $scheduledValue === $value;
}

/**
 * Return true when a queue's fixed schedule matches the supplied minute.
 */
function queue_stats_schedule_is_due(array $queue, DateTimeInterface $now): bool
{
    $schedule = strtolower(trim((string) ($queue['cron_schedule'] ?? 'never')));
    if ($schedule === '' || $schedule === 'never') {
        return false;
    }

    if (strtolower(trim((string) ($queue['cron_random'] ?? 'false'))) === 'true') {
        throw new QueueStatsScheduleException('random schedules are not supported');
    }

    $supportedSchedules = ['hourly', 'daily', 'weekly', 'monthly', 'annually', 'custom'];
    if (!in_array($schedule, $supportedSchedules, true)) {
        throw new QueueStatsScheduleException("unknown schedule '$schedule'");
    }

    $queueId = (string) ($queue['id'] ?? '');
    if (!preg_match('/^[0-9]+$/', $queueId)) {
        throw new QueueStatsScheduleException("invalid queue id '$queueId'");
    }

    $minuteMatches = queue_stats_cron_field_matches(
        $queue['cron_minute'] ?? null,
        (int) $now->format('i'),
        0,
        59
    );
    $hourMatches = queue_stats_cron_field_matches(
        $queue['cron_hour'] ?? null,
        (int) $now->format('G'),
        0,
        23
    );
    $monthMatches = queue_stats_cron_field_matches(
        $queue['cron_month'] ?? null,
        (int) $now->format('n'),
        1,
        12
    );
    $dayOfMonthMatches = queue_stats_cron_field_matches(
        $queue['cron_dom'] ?? null,
        (int) $now->format('j'),
        1,
        31
    );
    $dayOfWeekMatches = queue_stats_cron_field_matches(
        $queue['cron_dow'] ?? null,
        (int) $now->format('w'),
        0,
        6,
        true
    );

    $dayOfMonthIsWildcard = trim((string) ($queue['cron_dom'] ?? '')) === '*';
    $dayOfWeekIsWildcard = trim((string) ($queue['cron_dow'] ?? '')) === '*';

    // Vixie cron matches either day field when both are restricted.
    if (!$dayOfMonthIsWildcard && !$dayOfWeekIsWildcard) {
        $dayMatches = $dayOfMonthMatches || $dayOfWeekMatches;
    } else {
        $dayMatches = $dayOfMonthMatches && $dayOfWeekMatches;
    }

    return $minuteMatches && $hourMatches && $monthMatches && $dayMatches;
}

/**
 * Load the queue schedules from the FreePBX database.
 */
function queue_stats_fetch_schedules($database): array
{
    $sql = <<<'SQL'
SELECT
    qc.extension AS id,
    MAX(CASE WHEN qd.keyword = 'cron_schedule' THEN qd.data END) AS cron_schedule,
    MAX(CASE WHEN qd.keyword = 'cron_random' THEN qd.data END) AS cron_random,
    MAX(CASE WHEN qd.keyword = 'cron_minute' THEN qd.data END) AS cron_minute,
    MAX(CASE WHEN qd.keyword = 'cron_hour' THEN qd.data END) AS cron_hour,
    MAX(CASE WHEN qd.keyword = 'cron_dom' THEN qd.data END) AS cron_dom,
    MAX(CASE WHEN qd.keyword = 'cron_month' THEN qd.data END) AS cron_month,
    MAX(CASE WHEN qd.keyword = 'cron_dow' THEN qd.data END) AS cron_dow
FROM queues_config AS qc
LEFT JOIN queues_details AS qd
    ON qd.id = qc.extension
    AND qd.keyword IN (
        'cron_schedule',
        'cron_random',
        'cron_minute',
        'cron_hour',
        'cron_dom',
        'cron_month',
        'cron_dow'
    )
GROUP BY qc.extension
ORDER BY qc.extension
SQL;

    $statement = $database->query($sql);
    if ($statement === false) {
        throw new RuntimeException('failed to read queue schedules');
    }

    $queues = $statement->fetchAll(PDO::FETCH_ASSOC);
    if (!is_array($queues)) {
        throw new RuntimeException('failed to decode queue schedules');
    }

    return $queues;
}

/**
 * Produce a stable warning key that changes with the queue configuration.
 */
function queue_stats_warning_key(array $queue, string $reason): string
{
    $configuration = [];
    foreach (
        [
            'id',
            'cron_schedule',
            'cron_random',
            'cron_minute',
            'cron_hour',
            'cron_dom',
            'cron_month',
            'cron_dow',
        ] as $field
    ) {
        $configuration[$field] = $queue[$field] ?? null;
    }
    $configuration['reason'] = $reason;

    return hash('sha256', serialize($configuration));
}

/**
 * Write a warning once per container lifetime and queue configuration.
 */
function queue_stats_warn_once(string $key, string $message): void
{
    if (!is_dir(QUEUE_STATS_WARNING_DIR)) {
        @mkdir(QUEUE_STATS_WARNING_DIR, 0700, true);
    }

    $marker = QUEUE_STATS_WARNING_DIR . '/' . $key;
    $handle = @fopen($marker, 'x');
    if ($handle !== false) {
        fclose($handle);
        fwrite(STDERR, $message . PHP_EOL);
        return;
    }

    // If the marker directory is unavailable, retain the diagnostic even
    // though it cannot be rate limited.
    if (!file_exists($marker)) {
        fwrite(STDERR, $message . PHP_EOL);
    }
}

/**
 * Process all schedules. Reset failures make the run fail; bad queue
 * configuration is skipped and reported without failing every minute.
 */
function queue_stats_process_schedules(
    array $queues,
    DateTimeInterface $now,
    callable $resetQueue,
    callable $warn,
    callable $info,
    callable $error
): int {
    $failedResets = 0;

    foreach ($queues as $queue) {
        $queueId = (string) ($queue['id'] ?? 'unknown');

        try {
            $isDue = queue_stats_schedule_is_due($queue, $now);
        } catch (QueueStatsScheduleException $exception) {
            $reason = $exception->getMessage();
            $warn(
                queue_stats_warning_key($queue, $reason),
                "Skipping queue $queueId statistics reset: $reason"
            );
            continue;
        }

        if (!$isDue) {
            continue;
        }

        try {
            $resetQueue($queueId);
            $info("Reset statistics for queue $queueId");
        } catch (Throwable $exception) {
            $failedResets++;
            $error("Failed to reset statistics for queue $queueId: {$exception->getMessage()}");
        }
    }

    return $failedResets === 0 ? 0 : 1;
}

/**
 * Reset one queue through AMI and preserve the event emitted by the upstream
 * FreePBX queue_reset_stats.php command.
 */
function queue_stats_reset_queue($astman, string $queueId): void
{
    if (!preg_match('/^[0-9]+$/', $queueId)) {
        throw new InvalidArgumentException("invalid queue id '$queueId'");
    }

    $response = $astman->send_request(
        'Command',
        ['Command' => "queue reset stats $queueId"]
    );
    if (
        $response === false
        || (is_array($response) && strcasecmp((string) ($response['Response'] ?? ''), 'Error') === 0)
    ) {
        $message = is_array($response) ? ($response['Message'] ?? 'AMI command failed') : 'AMI command failed';
        throw new RuntimeException((string) $message);
    }

    $eventResponse = $astman->send_request(
        'UserEvent',
        [
            'userEvent' => 'reset-queue-stats',
            'queueId' => $queueId,
        ]
    );
    if (
        $eventResponse === false
        || (is_array($eventResponse)
            && strcasecmp((string) ($eventResponse['Response'] ?? ''), 'Error') === 0)
    ) {
        $message = is_array($eventResponse)
            ? ($eventResponse['Message'] ?? 'AMI user event failed')
            : 'AMI user event failed';
        throw new RuntimeException((string) $message);
    }
}

/**
 * Configure PHP's timezone explicitly: PHP otherwise defaults to UTC even
 * when Podman has configured /etc/localtime for the container.
 */
function queue_stats_configure_timezone(): void
{
    $timezone = trim((string) getenv('TIMEZONE'));
    if ($timezone === '' && is_readable('/etc/timezone')) {
        $timezone = trim((string) file_get_contents('/etc/timezone'));
    }

    if ($timezone === '' || !@date_default_timezone_set($timezone)) {
        throw new RuntimeException("invalid or missing NethVoice timezone '$timezone'");
    }
}

function queue_stats_main($database, $astman): int
{
    if (!is_object($astman) || !$astman->connected()) {
        throw new RuntimeException('Asterisk Manager Interface is not connected');
    }

    return queue_stats_process_schedules(
        queue_stats_fetch_schedules($database),
        new DateTimeImmutable('now'),
        static function (string $queueId) use ($astman): void {
            queue_stats_reset_queue($astman, $queueId);
        },
        static function (string $key, string $message): void {
            queue_stats_warn_once($key, $message);
        },
        static function (string $message): void {
            fwrite(STDOUT, $message . PHP_EOL);
        },
        static function (string $message): void {
            fwrite(STDERR, $message . PHP_EOL);
        }
    );
}

function queue_stats_is_direct_execution(): bool
{
    $script = $_SERVER['SCRIPT_FILENAME'] ?? '';
    return $script !== '' && realpath($script) === realpath(__FILE__);
}

if (queue_stats_is_direct_execution()) {
    try {
        queue_stats_configure_timezone();

        $restrict_mods = ['queues' => true, 'core' => true];
        $bootstrap_settings['cdrdb'] = true;
        $bootstrap_settings['freepbx_auth'] = false;
        require '/etc/freepbx.conf';

        $moduleInfo = module_getinfo('queues', MODULE_STATUS_ENABLED);
        if (!isset($moduleInfo['queues'])) {
            throw new RuntimeException('Queues module is missing or disabled');
        }

        exit(queue_stats_main(FreePBX::Database(), $astman));
    } catch (Throwable $exception) {
        fwrite(STDERR, 'Queue statistics scheduler failed: ' . $exception->getMessage() . PHP_EOL);
        exit(1);
    }
}
